<?php
declare(strict_types=1);
$tab=($_GET['tab']??'grades')==='assessments'?'assessments':'grades';
$title=$tab==='grades'?'History of Grades':'History of Assessments';
$role=Auth::role();
if($role==='TEACHER'){$permitted=StudentHistory::teacherStudents();$list=$tab==='grades'?array_values(array_filter(GS::students(),fn($s)=>isset($permitted[$s['id']]))):[];}
elseif($role==='STUDENT'){$own=StudentHistory::ownStudent();$list=$own?[$own]:[];}
else{$canBrowse=$tab==='grades'?StudentHistory::canViewAllGrades():Auth::can('registration','accounting','payments.view');$list=$canBrowse?GS::students():[];}
$id=is_string($_GET['id']??null)?$_GET['id']:'';
if(Auth::role()==='STUDENT'){
    $own=StudentHistory::ownStudent();
    if($id!=='' && (!$own || $id!==$own['id']))throw new Forbidden('You can view only your own history.');
    $id=$own['id']??'';
}
$account=Auth::central()->current();$showBalances=$role!=='STUDENT'||($account&&Auth::central()->can((int)$account['id'],'portal.balances.view'));$showReceipts=$role!=='STUDENT'?Auth::can('payments.view'):($account&&Auth::central()->can((int)$account['id'],'portal.receipts.view'));
$s=$id!==''?GS::get('students',$id):null;
if($id!==''&&(!$s||!StudentHistory::allowed($s,$tab)))throw new Forbidden('This student history is outside your permitted access.');
if(Auth::role()==='TEACHER' && $tab==='assessments')throw new Forbidden('Teachers cannot view financial history.');
if($isPost){if(!$s)throw new AppError('Choose a student.');StudentHistory::promote($s['id'],(string)($_POST['section']??''),(string)($_POST['reason']??''),($_POST['action']??'')==='graduate');flash('success','Student status updated. Previous records were preserved.');redirect('history',['id'=>$s['id'],'tab'=>$tab]);}
$snapshots=$s?StudentHistory::snapshots($s):[];
$grades=$s&&$tab==='grades'?StudentHistory::grades($s):[];
$regs=$s&&$tab==='assessments'?Db::all('SELECT * FROM sis_registrations WHERE student_doc_id=? ORDER BY school_year DESC,id DESC',[$s['id']]):[];
if (Auth::role()==='STUDENT') $regs=array_values(array_filter($regs,function($r){$a=Db::one('SELECT * FROM sis_portal_enrollments WHERE registration_id=?',[$r['id']]);return !$a || PortalEnrollment::visible($a,$r);}));
$periods=$snapshots;foreach($grades as $g)$periods[]=$g;foreach($regs as $r)$periods[]=['schoolYear'=>$r['school_year'],'yearLevel'=>$r['year_level'],'term'=>$r['term']];
$sy=is_string($_GET['sy']??null)?$_GET['sy']:'';$yl=is_string($_GET['year']??null)?$_GET['year']:'';$term=is_string($_GET['term']??null)?$_GET['term']:'';
$matches=fn($x)=>(!$sy||($x['schoolYear']??'')===$sy)&&(!$yl||($x['yearLevel']??'')===$yl)&&(!$term||($x['term']??'')===$term);
$years=array_values(array_unique(array_filter(array_column($periods,'schoolYear'))));rsort($years);if($sy!==''&&!in_array($sy,$years,true))$sy='';
$levels=array_values(array_unique(array_filter(array_column(array_filter($periods,fn($p)=>!$sy||($p['schoolYear']??'')===$sy),'yearLevel'))));
$terms=array_values(array_unique(array_filter(array_column(array_filter($periods,fn($p)=>(!$sy||($p['schoolYear']??'')===$sy)&&(!$yl||($p['yearLevel']??'')===$yl)),'term'))));
sort($levels,SORT_NATURAL);
if($yl!==''&&!in_array($yl,$levels,true))$yl='';if($term!==''&&!in_array($term,$terms,true))$term='';
$matches=fn($x)=>(!$sy||($x['schoolYear']??'')===$sy)&&(!$yl||($x['yearLevel']??'')===$yl)&&(!$term||($x['term']??'')===$term);
layout_start($title);$gradeShortcut=StudentHistory::canViewAllGrades()||($account&&Auth::central()->can((int)$account['id'],$role==='STUDENT'?'portal.grades.view':'grading.grades.view'));
$financeShortcut=$role==='STUDENT'?($account&&Auth::central()->can((int)$account['id'],'portal.assessment.view')):($role!=='TEACHER'&&Auth::can('registration','accounting','payments.view'));
page_title($role==='STUDENT'?$title:'Students','<div class="d-flex flex-wrap gap-2">'.($gradeShortcut?'<a class="btn btn-outline-primary" href="'.url('history',['id'=>$id,'tab'=>'grades']).'">History of Grades</a>':'').($financeShortcut?'<a class="btn btn-outline-primary" href="'.url('history',['id'=>$id,'tab'=>'assessments']).'">History of Assessments</a>':'').'</div>','Permanent history. Promotion and graduation preserve previous records.');
?>
<section class="form-section"><h2 class="h5"><?= h($title) ?></h2>
<form method="get" class="row g-3"><input type="hidden" name="r" value="history"><input type="hidden" name="tab" value="<?= h($tab) ?>">
<?php if(Auth::role()!=='STUDENT'): ?><div class="col-12"><label class="form-label" for="historyStudent">Student</label><select class="form-select" name="id" id="historyStudent" data-autosubmit><option value="">Choose a student</option><?php foreach($list as $item): ?><option value="<?= h($item['id']) ?>"<?= $id===$item['id']?' selected':'' ?>><?= h($item['studentId'].' · '.$item['studentName']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<div class="col-md-4"><label class="form-label">School year</label><select class="form-select" name="sy" data-autosubmit><?= list_options($years,$sy,'All school years') ?></select></div><div class="col-md-4"><label class="form-label">Year level</label><select class="form-select" name="year" data-autosubmit><?= list_options($levels,$yl,'All year levels') ?></select></div><div class="col-md-4"><label class="form-label">Term</label><select class="form-select" name="term" data-autosubmit><?= list_options($terms,$term,'All terms') ?></select></div><div><button class="btn btn-primary">View history</button></div></form></section>
<?php if(!$s): ?><div class="alert alert-info">Choose a permitted student to view their history. Unlinked applicants have no student history yet.</div><?php else: ?>
<section class="form-section"><h2 class="h5"><?= h($s['studentName']) ?></h2><p><?= h($s['studentId'].' · '.($s['status']??'Active')) ?></p>
<?php if($tab==='grades'): ?>
<?php if(Auth::role()==='STUDENT'&&Settings::on('portal_hide_grades_unpaid')): ?><p class="small text-muted">The school's unpaid-balance visibility policy applies to historical grades.</p><?php endif; ?>
<?php if(Auth::role()!=='TEACHER'): ?><?= grades_html(array_values(array_filter($grades,$matches)),'No released final grades match this period.') ?><?php endif; ?>
<?php if(Auth::role()!=='STUDENT'): ?><h3 class="h6 mt-3"><?= Auth::role()==='TEACHER'?'Your grade entries for this student (read only)':'Existing grade entries (read only)' ?></h3><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Period</th><th>Subject</th><th>Teacher</th><th>Grade / Mark</th><th>Status</th></tr></thead><tbody><?php foreach(StudentHistory::gradeEntries((string)$s['id']) as $g):if(!$matches($g))continue; ?><tr><td><?= h(($g['schoolYear']??'').' · '.($g['term']??'')) ?></td><td><?= h(($g['subjectCode']??'').' '.($g['subjectName']??'')) ?></td><td><?= h($g['teacherName']??'') ?></td><td><?= h(($g['mark']??'')?:($g['finalGrade']??'')) ?></td><td><?= h($g['status']??'Draft') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php else: $shown=0;foreach($regs as $r): if(!$matches(['schoolYear'=>$r['school_year'],'yearLevel'=>$r['year_level'],'term'=>$r['term']]))continue;$shown++;$feeRemaining=array_column(AccountingWorkflow::feeBalances($r),'remaining','id'); ?>
<article class="border rounded p-3 mb-3"><h3 class="h6"><?= h($r['school_year'].' · '.$r['year_level'].' · '.$r['term'].' · '.$r['reg_no']) ?> <?= badge($r['status']) ?></h3><p class="small"><?= ($r['record_origin']??'')==='MIGRATION'?'Migrated opening balances':'Existing SIS assessment' ?> · <?= h($r['section_name']) ?></p>
<div class="table-responsive"><table class="table table-sm"><thead><tr><th>Category</th><th>Fee</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach(Db::all('SELECT * FROM sis_registration_items WHERE registration_id=? ORDER BY sort_order,id',[$r['id']]) as $fee): ?><tr><td><?= h($fee['category_name']) ?></td><td><?= h($fee['label_name']) ?></td><td class="text-end">₱<?= Money::fmt(Money::cents($fee['amount'])) ?><?php if($showBalances&&$r['locked_at']&&Money::cents($fee['amount'])>0): ?><br><small>Remaining ₱<?= Money::fmt((int)($feeRemaining[$fee['id']]??0)) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<p>Total ₱<?= Money::fmt(Money::cents($r['total_amount'])) ?><?php if($showBalances): ?> · Paid ₱<?= Money::fmt(Money::cents($r['amount_paid'])) ?> · Balance ₱<?= Money::fmt($r['status']==='CANCELLED'?0:Registration::balance($r)) ?><?php endif; ?></p>
<?php if($showReceipts)foreach(Db::all('SELECT * FROM sis_payments WHERE registration_id=? ORDER BY paid_at,id',[$r['id']]) as $payment): ?><p class="small mb-1"><a href="<?= url('receipt',['id'=>$payment['id']]) ?>"><?= h($payment['receipt_no']) ?></a> · <?= h($payment['paid_at'].' · '.$payment['status']) ?> · ₱<?= Money::fmt(Money::cents($payment['amount'])) ?></p><?php endforeach; ?>
<?php foreach(Db::all("SELECT d.*,j.entry_date,j.memo,j.reversed_by_id FROM sis_accounting_documents d JOIN sis_journal j ON j.id=d.journal_id WHERE d.registration_id=? AND j.status='POSTED' ORDER BY d.id",[$r['id']]) as $doc): ?><p class="small"><?= h(AccountingWorkflow::KINDS[$doc['kind']].' · '.$doc['reference_no'].' · '.$doc['entry_date']) ?> · ₱<?= Money::fmt(Money::cents($doc['amount'])) ?> <?= $doc['reversed_by_id']?'(Reversed)':'' ?></p><?php endforeach; ?>
<?php if(Auth::can('payments.record')&&$r['status']==='REGISTERED'&&Registration::balance($r)>0): ?><a class="btn btn-sm btn-outline-primary" href="<?= url('cashier',['reg'=>$r['id']]) ?>">Receive payment</a><?php endif; ?></article>
<?php endforeach;if(!$shown): ?><p class="text-muted">No assessments match this period.</p><?php endif;endif; ?></section>
<section class="form-section"><h2 class="h6">Enrollment and status history</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>School year</th><th>Year level</th><th>Term</th><th>Section</th><th>Status</th></tr></thead><tbody><?php foreach(array_filter($snapshots,$matches) as $p): ?><tr><td><?= h($p['schoolYear']) ?></td><td><?= h($p['yearLevel']) ?></td><td><?= h($p['term']?:'Directory snapshot') ?></td><td><?= h($p['sectionName']) ?></td><td><?= h($p['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if(Auth::can('registration')&&($s['status']??'')!=='graduated'): ?><section class="form-section"><h2 class="h6">Promotion or graduation</h2><p class="small">All second-semester subjects must be finalized as Passed. Earlier grades, assessments, receipts and balances stay in their original periods. Promotion selects the next-year section; create the new enrollment through Registration.</p><form method="post" data-confirm="Update this student's status while keeping the previous records?"><?= csrf_field() ?><label class="form-label">Next section (promotion only)</label><select name="section" class="form-select mb-2"><option value="">Choose next-year section</option><?php foreach(GS::sections() as $sec)if($sec['schoolYear']>($s['schoolYear']??'')): ?><option value="<?= h($sec['id']) ?>"><?= h($sec['schoolYear'].' · '.$sec['yearLevel'].' · '.$sec['sectionName']) ?></option><?php endif; ?></select><label class="form-label">Reason</label><input name="reason" class="form-control mb-2" required minlength="8" maxlength="1000"><button name="action" value="promote" class="btn btn-primary">Promote</button> <button name="action" value="graduate" class="btn btn-outline-primary">Mark Graduated</button></form></section><?php endif;endif;layout_end();
